#!/usr/bin/env python3
"""Execute entire original Audio preferences with real Fumen notifier and Undo queue."""
import argparse,subprocess,tempfile,json,hashlib
from pathlib import Path
p=argparse.ArgumentParser()
for k in ['editor-root','reference-root','dotnet','output']:p.add_argument('--'+k,type=Path,required=True)
a=p.parse_args();pin='48e18f71655d0f0d86144c63239331833501fda2';fp='0fe292f9c0ef70fb77d61cb54316a7e78dbf3c89'
for path,rev in [(a.editor_root,pin),(a.reference_root/'Fumen',fp)]:assert subprocess.check_output(['git','-C',str(path),'rev-parse','HEAD'],text=True).strip()==rev
source=subprocess.check_output(['git','-C',str(a.editor_root),'show',pin+':StepManiaEditor/Preferences/PreferencesAudio.cs'],text=True,encoding='utf-8-sig')
adapter='''using System.Text.Json;using Fumen;using StepManiaEditor;
namespace StepManiaEditor {class Preferences {public static Preferences Instance=new();public PreferencesAudio PreferencesAudio=new();}class Observer:Fumen.IObserver<PreferencesAudio>{public List<string> Events=[];public void OnNotify(string id,PreferencesAudio p,object payload)=>Events.Add(id);}}
class Program {
static void Mutate(PreferencesAudio p){p.MusicRate=1.25;p.AudioOffset=-.0125;p.MainVolume=.4f;p.MusicVolume=.3f;p.AssistTickVolume=.2f;p.AssistTickAttackTime=.005f;p.UseAssistTick=true;p.SkipAssistTickOnBeatTick=true;p.BeatTickVolume=.1f;p.BeatTickAttackTime=.007f;p.UseBeatTick=true;p.SkipBeatTickOnAssistTick=true;p.DspBufferSize=256;p.DspNumBuffers=3;p.PreviewFadeInTime=.25;p.PreviewFadeOutTime=.75;}
static void Main(){var options=new JsonSerializerOptions{IncludeFields=true};var output=new List<object>();foreach(var json in new[]{"{}","{\\"ShowAudioPreferencesWindow\\":true}","{\\"MusicRate\\":8,\\"AudioOffset\\":-4,\\"MainVolume\\":-2,\\"MusicVolume\\":3,\\"AssistTickAttackTime\\":-1,\\"DspBufferSize\\":-1,\\"DspNumBuffers\\":99}"}){var p=JsonSerializer.Deserialize<PreferencesAudio>(json,options);Preferences.Instance.PreferencesAudio=p;var normalized=JsonSerializer.SerializeToElement(p,options);var o=new Observer();p.AddObserver(o);Mutate(p);var changed=JsonSerializer.SerializeToElement(p,options);var notifications=o.Events.ToArray();o.Events.Clear();Mutate(p);var duplicateNotifications=o.Events.ToArray();p.RestoreDefaults();var restored=JsonSerializer.SerializeToElement(p,options);var restoreNotifications=o.Events.ToArray();o.Events.Clear();ActionQueue.Instance.Undo();var undone=JsonSerializer.SerializeToElement(p,options);var undoNotifications=o.Events.ToArray();o.Events.Clear();ActionQueue.Instance.Redo();var redone=JsonSerializer.SerializeToElement(p,options);var redoNotifications=o.Events.ToArray();o.Events.Clear();p.RestoreDefaults();var noOpNotifications=o.Events.ToArray();output.Add(new{Input=JsonDocument.Parse(json).RootElement.Clone(),Normalized=normalized,Changed=changed,Notifications=notifications,DuplicateNotifications=duplicateNotifications,Restored=restored,RestoreNotifications=restoreNotifications,Undone=undone,UndoNotifications=undoNotifications,Redone=redone,RedoNotifications=redoNotifications,NoOpNotifications=noOpNotifications});ActionQueue.Instance.Clear();}Console.Write(JsonSerializer.Serialize(output));}}
'''
with tempfile.TemporaryDirectory(prefix='audio-preferences-oracle-') as d:
 t=Path(d);(t/'Audio.cs').write_text(source);(t/'Program.cs').write_text(adapter);dll=a.reference_root/'Fumen/Fumen/bin/Release/net10.0/Fumen.dll';(t/'Oracle.csproj').write_text(f'<Project Sdk="Microsoft.NET.Sdk"><PropertyGroup><OutputType>Exe</OutputType><TargetFramework>net10.0</TargetFramework><ImplicitUsings>enable</ImplicitUsings><Nullable>disable</Nullable></PropertyGroup><ItemGroup><Reference Include="Fumen"><HintPath>{dll}</HintPath></Reference></ItemGroup></Project>');subprocess.run([str(a.dotnet),'build',str(t/'Oracle.csproj'),'-c','Release','--nologo','-v','quiet'],check=True);assembly=t/'bin/Release/net10.0/Oracle.dll';result=json.loads(subprocess.check_output([str(a.dotnet),str(assembly)],text=True));sha=hashlib.sha256(assembly.read_bytes()).hexdigest()
a.output.write_text(json.dumps(result,indent=2)+'\n');a.output.with_suffix('.reference.json').write_text(json.dumps({'EditorCommit':pin,'FumenCommit':fp,'SourceSha256':hashlib.sha256(source.encode()).hexdigest(),'AdapterSha256':hashlib.sha256(adapter.encode()).hexdigest(),'AssemblySha256':sha,'FumenAssemblySha256':hashlib.sha256(dll.read_bytes()).hexdigest(),'Scope':'Whole original PreferencesAudio class, all16 business fields +window state, real Fumen observer notifications and actual Restore/Undo/Redo action/queue. Source has no PostLoad. Does not execute FMOD, MusicManager scheduling or output backend.'},indent=2)+'\n');print('Executed',len(result),'whole source Audio preferences/notifications/history cases.')
